cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/4e13d33a-67a1-4a9a-87d3-4bb0f73ece21/scratchpad; cat > kubiak.py <<'E'
from kub_parse import *
SRC="Kubiak PJ (2009) Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia 11(1), 131-165."
FN='Kubiak Cunn 2009'
LCRN='Lane Cove River catchment'; NLN='Narrabeen Lagoon catchment'
def fmt(x):
    s=f'{x:.3f}'.rstrip('0').rstrip('.'); return s
def conv(v,unit):
    # v like '12', '12-20', '>35', '<1'
    if unit=='years': return v
    pre=''
    if v[0] in '<>': pre=v[0]; v=v[1:]
    parts=[fmt(float(p)/52) for p in v.split('-')]
    return pre+'-'.join(parts)
TIME_RE=re.compile(r'^\s*(?:c\.\s*)?\??\s*(\d+(?:\.\d+)?)(?:\s*(?:–|-)\s*(\d+(?:\.\d+)?))?(\+)?\s*(w|y)?')
def ptime(cell):
    """returns (value or None, unit or None, note or None)"""
    if not cell: return None,None,None
    s=cell.replace('<u>','').replace('</u>','').replace('**','').strip()
    m=re.match(r'At least (\d+(?:\.\d+)?) years?',s)
    if m: return '>'+m.group(1),'years',f'printed "{cell}"'
    m=re.match(r'Less than (\d+(?:\.\d+)?) years?',s)
    if m: return '<'+m.group(1),'years',f'printed "{cell}"'
    m=TIME_RE.match(s)
    if not m or not re.match(r'^\s*(c\.|\?)?\s*\d',s):
        return None,None,f'text: "{cell}"'
    a,b,plus,u=m.groups()
    if u is None:
        u2=re.search(r'\d\s*(w|y)\b',s[m.end():])  # unit later in string
        u2=re.search(r'(\d|\+)(w|y)',s[m.end():])
        u=u2.group(2) if u2 else None
    if u is None: return None,None,f'unit unclear: "{cell}"'
    unit={'w':'weeks','y':'years'}[u]
    val=a+('-'+b if b else '')
    if plus: val='>'+a
    simple=re.fullmatch(r'\d+(?:\.\d+)?w',s)
    note=None if simple else f'printed "{cell}"'
    return val,unit,note
def pcode(raw):
    """returns dict(value, dom, note) or None"""
    if not raw: return None
    t=raw.strip()
    if t.startswith('R(1)m.i.f'):
        return dict(value='resprouter',dom='R',note=f'LCR cell printed "{t}"')
    m=re.match(r'^(\?|p)?\s?([RKrk])(?:\s?(/|;)\s?(\?|p)?\s?([RKrk]))?',t)
    if not m: return dict(value=None,dom=None,note=f'text: "{t}"',textonly=True)
    p1,c1,sep,p2,c2=m.groups()
    clean=c1+(sep+c2 if sep else '')
    rest=t[m.end():]
    note=None
    if sep:
        value=clean; d=c1 if (c1.isupper() and c2.islower()) else None
    elif c1.isupper():
        value={'R':'resprouter','K':'obligate'}[c1]; d=c1
    else:
        value=c1; d=None
    flags=[]
    if p1=='p' or p2=='p': flags.append('p = probably')
    if '?' in (p1 or '')+(p2 or ''): flags.append('? = possibly')
    if p1 or p2 or rest.strip() or (sep and False):
        note=f'printed "{t}"'+(f' ({"; ".join(flags)})' if flags else '')
    elif c1.islower() and not sep:
        note=f'printed "{t}" (lowercase code: small proportion of adult plants)'
    return dict(value=value,dom=d,note=note)
def split_name(n):
    notes=[]
    exotic=n.startswith('*')
    n=n.lstrip('*')
    unsure_exotic=False
    if n.startswith('(*?)'): n=n[4:]; unsure_exotic=True; notes.append('paper marks taxon (*?): possibly exotic; not marked as introduced')
    m=re.match(r'^(\S+) (\S.*)$',n)
    g,rest=m.groups()
    # extras
    extras=[]
    for pat in (r' \(s\.lat\.\)',r' \(s\.str\.\)',r' \(syn\. [^)]*\)'):
        mm=re.search(pat,rest)
        if mm: extras.append(mm.group(0).strip()); rest=rest.replace(mm.group(0),'')
    if extras: notes.append('name printed with '+' '.join(extras))
    infra=''
    mm=re.search(r' ((?:subsp\.|var\.|cv\.) .*)$',rest)
    if mm: infra=mm.group(1); rest=rest[:mm.start()]
    if rest.startswith('?') or infra.find('?')>=0 or '?' in rest:
        notes.append('paper marks identification as uncertain (?)')
        rest=rest.replace('?',''); infra=infra.replace('?','')
    return g,rest,infra,exotic,notes
def dom_set(codes):
    return {c['dom'] for c in codes if c and c.get('dom')}
def build():
    out=[];info=[];skipped=[]
    for pi,grp,c in rows:
        fam,name,peaks,lcr,nl,seedl,ffr,ffs,frr,frs,pjp,sjp=c
        g,s,infra,exotic,nn=split_name(name)
        page=130+pi
        codes={'LCR':pcode(lcr),'NL':pcode(nl)}
        coded=[k for k,v in codes.items() if v and not v.get('textonly')]
        # time values
        tnotes=[]; vals={}
        bridged=None
        if ffr.startswith('<u>') and ffs==ffr: bridged=ffr; ffr=ffs=''
        elif ffr.startswith('<u>') or ffs.startswith('<u>'):
            bridged=ffr if ffr.startswith('<u>') else ffs
            if ffr.startswith('<u>'): ffr=''
            else: ffs=''
        def put(col,cell,fixed_years,label):
            v,u,n=ptime(cell)
            if v is None:
                if n: tnotes.append(f'{label} {n}')
                return
            if fixed_years:
                nv=conv(v,u)
                vals[col]=nv
                if u=='weeks':
                    tnotes.append(f'{col} converted from {v} weeks')
                    if n: tnotes.append(f'{label} {n}')
                elif n: tnotes.append(f'{label} {n}')
            else:
                vals[col]=v; vals['Time_unit']=u
                if n: tnotes.append(f'{label} {n}')
        put('Time to first flower production resprout_repr3a',ffr,True,'first flowering (resprouts)')
        put('Age at first flower production from seed_repr3',ffs,True,'first flowering (from seed)')
        if bridged:
            ds=dom_set(codes.values())
            if ds=={'K'}: col='Age at first flower production from seed_repr3'; why='fire response K: plants assumed to grow from seed'
            elif ds=={'R'}: col='Time to first flower production resprout_repr3a'; why='fire response R: plants resprouted'
            else: col=None
            if col and col not in vals:
                put(col,bridged,True,'first flowering (underlined)')
                tnotes.append(f'first flowering time underlined in paper (bridges resprout and seed columns, unclear which); placed under {"seed" if "seed" in col else "resprout"} column because {why}')
            else:
                v,u,n=ptime(bridged)
                tnotes.append(f'first flowering time {bridged.replace("<u>","").replace("</u>","")} underlined in paper (bridges resprout and seed columns, unclear which); no fire response to decide, not placed in a time column')
        put('primary_juvenile_period',pjp,True,'primary juvenile period')
        put('secondary_juvenile_period',sjp,False,'secondary juvenile period')
        for lab,v in (('first fruiting (resprouts)',frr),('first fruiting (from seed)',frs)):
            if v: tnotes.append(f'{lab} {v.replace("<u>","").replace("</u>","")}'+(' underlined' if '<u>' in v else ''))
        if seedl: tnotes.append(f'seedlings first observed {seedl}')
        if peaks: tnotes.append(f'post-fire peak {peaks}')
        rownotes=[]
